<?php
require_once dirname(__DIR__) . '/_common.php';
$id=isset($_GET['id'])?(int)$_GET['id']:0;$stmt=$pdo->prepare('SELECT * FROM pengumuman WHERE id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){osis_set_flash('error','Pengumuman tidak ditemukan.');osis_redirect('admin/pengumuman/index.php');}
$pageTitle='Edit pengumuman';$error='';
if(osis_admin_is_post()){osis_verify_csrf();$judul=osis_post_string('judul',180);$isi=osis_post_string('isi',20000);$penting=isset($_POST['penting'])&&$_POST['penting']==='ya'?'ya':'tidak';if($judul===''||$isi===''){$error='Judul dan isi wajib diisi.';}else{try{$stmt=$pdo->prepare('UPDATE pengumuman SET judul=?,isi=?,penting=? WHERE id=?');$stmt->execute([$judul,$isi,$penting,$id]);osis_log_activity('Memperbarui pengumuman: '.$judul);osis_set_flash('success','Pengumuman berhasil diperbarui.');osis_redirect('admin/pengumuman/index.php');}catch(PDOException $exception){$error=osis_admin_handle_error($exception);}}}
osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap"><a class="back-link" href="<?=osis_e(osis_url('admin/pengumuman/index.php'))?>">← Semua pengumuman</a><div class="admin-panel form-panel"><span class="eyebrow">PERBARUI INFORMASI</span><h2>Edit pengumuman</h2><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" data-validate-form><?=osis_csrf_input()?><label for="judul">Judul</label><input id="judul" name="judul" required maxlength="180" value="<?=osis_e(isset($_POST['judul'])?$_POST['judul']:$item['judul'])?>"><label for="isi">Isi pengumuman</label><textarea id="isi" name="isi" rows="10" required><?=osis_e(isset($_POST['isi'])?$_POST['isi']:$item['isi'])?></textarea><label class="check-line"><input type="checkbox" name="penting" value="ya" <?=isset($_POST['penting'])? 'checked':($item['penting']==='ya'?'checked':'')?>><span>Tandai sebagai pengumuman penting <small>Tampil dengan penanda dan urutan teratas.</small></span></label><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/pengumuman/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Simpan perubahan <span>↗</span></button></div></form></div></div>
